/** A real calendar date in the register's ISO form YYYY-MM-DD; placeholders such as TBD or pending are not dates. */
function isIsoDate(value) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!m) return false;
  const [year, month, day] = m.slice(1).map(Number);
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1] || 0;
  return day >= 1 && day <= days;
}

/** Text of accepted decisions: register rows with a valid Date, plus the docs/decisions/ records they link. */
function acceptedDecisionText(root) {
  if (!lib.exists(root, REGISTER)) return '';
  const text = lib.readText(root, REGISTER);
  const start = text.indexOf('## Accepted decisions');
  if (start < 0) return '';
  const rows = [];
  for (const line of text.slice(start).split(/\r?\n/).slice(1)) {
    if (/^#{1,6}\s/.test(line)) break;
    if (!/^\s*\|/.test(line) || /^\s*\|\s*:?-/.test(line)) continue;
    const cells = line.trim().replace(/^\||\|$/g, '').split('|').map(c => c.trim());
    if (!isIsoDate(cells[0])) continue; // undated, placeholder, or invalid Date: not an accepted decision
    let row = cells.join(' ');
    for (const m of row.matchAll(/docs\/decisions\/[\w.-]+\.md/g)) {
      if (lib.exists(root, m[0])) row += `\n${lib.readText(root, m[0])}`;
    }
    rows.push(row);
  }
  return rows.join('\n').replace(/→/g, '->').replace(/[ \t]+/g, ' ');
}

const escapeRegex = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** An edge is approved when an accepted decision lists it as `From -> To`. */
function isApprovedEdge(approvals, from, to) {
  return new RegExp(`(?<![\\w.])${escapeRegex(from)}\\s*->\\s*${escapeRegex(to)}(?![\\w.])`, 'i').test(approvals);
}

/** A project addition or removal is approved when an accepted decision names the project. */
function isApprovedProject(approvals, name) {
  return new RegExp(`(?<![\\w.])${escapeRegex(name)}(?![\\w.])`, 'i').test(approvals);
}

function dotnetFindings(words, cwd, segment) {
  let i = 1;
  while (i < words.length && words[i].startsWith('-')) i += 1; // host options such as --diagnostics
  const verb = (words[i] || '').toLowerCase();
  const rest = words.slice(i + 1);
  if (rest.some(w => /^(-h|--help|-\?|\/\?)$/.test(w))) return [];
  let kind;
  let action;
  let project = null;
  let args;
  if (verb === 'add' || verb === 'remove') {
    const j = rest.findIndex(w => /^(package|reference)$/i.test(w));
    if (j < 0) return [];
    kind = rest[j].toLowerCase();
    action = verb;
    project = rest.slice(0, j).find(w => !w.startsWith('-')) || null;
    args = rest.slice(j + 1);
  } else if ((verb === 'package' || verb === 'reference') && /^(add|remove|update)$/i.test(rest[0] || '')) {
    kind = verb;
    action = rest[0].toLowerCase();
    args = rest.slice(1);
  } else {
    return [];
  }
  const opts = {};
  const positional = [];
  for (let k = 0; k < args.length; k += 1) {
    const m = /^(--?[A-Za-z][\w-]*)(?:[=:](.*))?$/.exec(args[k]);
    if (m) {
      const name = m[1].toLowerCase();
      let value = m[2];
      if (value === undefined && DOTNET_VALUE_OPTIONS.has(name)) value = args[(k += 1)];
      opts[name] = value === undefined ? true : value;
      continue;
    }
    positional.push(args[k]);
  }
  if (typeof opts['--project'] === 'string') project = opts['--project'];
  if (kind === 'reference') {
    if (action === 'update') return [];
    const from = projectName(project, cwd);
    const edges = positional.map(ref => ({ from, to: projectName(ref, cwd) }));
    return [{ kind: 'reference-change', segment, action, edges }];
  }
  if (action === 'remove') return [{ kind: 'dependency-removal', segment, specs: positional }];
  const [id, inlineVersion] = String(positional[0] || '').split('@');
  if (!id && action === 'update') return [{ kind: 'dependency-update', segment }];
  const version = opts['--version'] || opts['-v'] || inlineVersion;
  if (!id || typeof version !== 'string' || !EXACT_NUGET.test(version)) {
    return [{ kind: 'dependency-version', segment, specs: [id || '(no package id)'] }];
  }
  return [];
}

